import 'package:flutter/material.dart';import '../services/download_service.dart';
class HistoryPage extends StatefulWidget{const HistoryPage({super.key});@override State<HistoryPage> createState()=>_HistoryPageState();}
class _HistoryPageState extends State<HistoryPage>{final s=DownloadService();List<DownloadRecord> r=[];@override void initState(){super.initState();load();}Future<void>load()async{final x=await s.history();if(mounted)setState(()=>r=x);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Riwayat'),actions:[IconButton(onPressed:r.isEmpty?null:()async{await s.clearHistory();load();},icon:const Icon(Icons.delete_sweep_rounded))]),body:r.isEmpty?const Center(child:Text('Belum ada riwayat download.')):RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:r.length,itemBuilder:(_,i)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.video_file_rounded)),title:Text(r[i].title,maxLines:2,overflow:TextOverflow.ellipsis),subtitle:Text(r[i].createdAt.toLocal().toString())))));}
